package io.github.chronicle.quietbelow.content;

import io.github.chronicle.core.offering.temporary.*;
import io.github.chronicle.core.server.*;
import net.fabricmc.fabric.api.entity.event.v1.ServerPlayerEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.entity.effect.StatusEffect;
import net.minecraft.entity.effect.StatusEffectInstance;
import net.minecraft.entity.effect.StatusEffects;
import net.minecraft.item.ItemStack;
import net.minecraft.item.Items;
import net.minecraft.registry.Registries;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.sound.SoundCategory;
import net.minecraft.sound.SoundEvents;
import net.minecraft.text.Text;
import net.minecraft.util.Hand;
import net.minecraft.util.math.BlockPos;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Quiet Below prices, exact external mutations, flavor and active Night Vision/local aura behavior. */
public final class TemporaryAltarOfferings {
    private static final int MAX_ACTIVE_HARVESTS=16;
    public static final String EMERGENCY_ID="quiet_below:emergency_healing",REPAIR_ID="quiet_below:repair",SIGHT_ID="quiet_below:cave_sight",HARVEST_ID="quiet_below:harvest";
    public static final TemporaryOfferings.Definition EMERGENCY=new TemporaryOfferings.Definition(EMERGENCY_ID,new EmergencyHandler());
    public static final TemporaryOfferings.Definition REPAIR=new TemporaryOfferings.Definition(REPAIR_ID,new RepairHandler());
    public static final TemporaryOfferings.Definition SIGHT=new TemporaryOfferings.Definition(SIGHT_ID,new SightHandler());
    public static final TemporaryOfferings.Definition HARVEST=new TemporaryOfferings.Definition(HARVEST_ID,new HarvestHandler());
    private static final Map<MinecraftServer,Map<UUID,StatusEffectInstance>> OWNED_SIGHT=new IdentityHashMap<>();
    private static boolean registered;
    private TemporaryAltarOfferings(){}
    public static void register(){if(registered)return;registered=true;AltarOfferingConfig.register();for(var definition:List.of(EMERGENCY,REPAIR,SIGHT,HARVEST))TemporaryOfferings.registerDefinition(definition);
        ServerTickEvents.END_SERVER_TICK.register(TemporaryAltarOfferings::tick);ServerDisconnects.register((handler,server)->disconnect(handler.player));ServerPlayerEvents.AFTER_RESPAWN.register((oldPlayer,player,alive)->withdrawMarked(player));ServerLifecycleEvents.SERVER_STOPPED.register(server->{clear(server);OWNED_SIGHT.remove(server);});}
    public static TemporaryOfferings.Station station(ServerWorld world,BlockPos position,Hand hand){if(!(world.getBlockEntity(position) instanceof AncientAltarBlockEntity altar))throw new IllegalStateException("The original Altar is no longer here.");String dimension=world.getRegistryKey().getValue().toString(),stationId=altar.stationId().toString();return new TemporaryOfferings.Station(dimension+"|"+stationId,Map.of("dimension",dimension,"x",Integer.toString(position.getX()),"y",Integer.toString(position.getY()),"z",Integer.toString(position.getZ()),"hand",hand.name(),"station_uuid",stationId));}
    public static int cropPercent(MinecraftServer server,String dimension,int x,int y,int z){return growthAuras(server,dimension).stream().filter(a->distance(a,x,y,z)<=a.radius*a.radius).mapToInt(Aura::cropPercent).max().orElse(100);}
    public static List<Aura> growthAuras(MinecraftServer server,String dimension){ServerWorld world=server.getWorld(net.minecraft.registry.RegistryKey.of(net.minecraft.registry.RegistryKeys.WORLD,net.minecraft.util.Identifier.of(dimension)));if(world==null)return List.of();return TemporaryOfferings.active(server,AncientAltars.SOURCE).stream().filter(claim->claim.offering().equals(HARVEST_ID)&&claim.terms().evidence().get("dimension").equals(dimension)).map(TemporaryAltarOfferings::aura).filter(Objects::nonNull).filter(a->AncientAltars.isStation(world,new BlockPos(a.x,a.y,a.z),a.stationId)).limit(MAX_ACTIVE_HARVESTS).toList();}
    public record Aura(String stationId,int x,int y,int z,int radius,int cropPercent,int growthPercent){}
    private static long distance(Aura a,int x,int y,int z){long dx=(long)a.x-x,dy=(long)a.y-y,dz=(long)a.z-z;return dx*dx+dy*dy+dz*dz;}
    private static Aura aura(TemporaryOfferingClaim claim){try{var e=claim.terms().evidence();UUID.fromString(e.get("station_uuid"));return new Aura(e.get("station_uuid"),Integer.parseInt(e.get("x")),Integer.parseInt(e.get("y")),Integer.parseInt(e.get("z")),Integer.parseInt(e.get("radius")),Integer.parseInt(e.get("crop_percent")),Integer.parseInt(e.get("growth_percent")));}catch(RuntimeException error){return null;}}
    private static abstract class Handler implements TemporaryOfferings.Handler {
        final void enabled(boolean value){if(!value)throw new IllegalStateException("This prayer is disabled by the operator.");}
        final boolean active(ServerPlayerEntity player,String offering){return TemporaryOfferings.active(player.getEntityWorld().getServer(),AncientAltars.SOURCE).stream().anyMatch(claim->claim.player().equals(player.getUuid())&&claim.offering().equals(offering));}
        final void aftermath(ServerPlayerEntity player,TemporaryOfferings.Station station,String text){player.sendMessage(Text.literal(text),false);BlockPos pos=new BlockPos(Integer.parseInt(station.context().get("x")),Integer.parseInt(station.context().get("y")),Integer.parseInt(station.context().get("z")));player.getEntityWorld().playSound(null,pos,SoundEvents.BLOCK_ENCHANTMENT_TABLE_USE,SoundCategory.BLOCKS,.8f,.65f);}
    }
    private static final class EmergencyHandler extends Handler {
        @Override public TemporaryOfferingTerms preview(ServerPlayerEntity donor,TemporaryOfferings.Station station){var config=AltarOfferingConfig.get().emergency();enabled(config.enabled());if(donor.getHealth()<=config.donorHealth())throw new IllegalStateException("The donor cannot survive this prayer.");List<ServerPlayerEntity> recipients=PlayRuntime.eligiblePlayers(donor.getEntityWorld().getServer()).stream().filter(player->player!=donor&&player.getEntityWorld()==donor.getEntityWorld()&&player.squaredDistanceTo(donor)<=config.radius()*config.radius()&&player.getHealth()<player.getMaxHealth()).sorted(Comparator.comparing(player->player.getUuid().toString())).toList();Map<UUID,Float> shares=shares(recipients,config.healing());if(shares.isEmpty())throw new IllegalStateException("No nearby participant can receive sheltering grace.");TreeMap<String,String> evidence=new TreeMap<>();evidence.put("donor_health",Float.toString(donor.getHealth()));evidence.put("donor_cost",Integer.toString(config.donorHealth()));evidence.put("healing",Integer.toString(config.healing()));evidence.put("radius",Integer.toString(config.radius()));StringJoiner joined=new StringJoiner(",");for(var entry:shares.entrySet()){var recipient=donor.getEntityWorld().getServer().getPlayerManager().getPlayer(entry.getKey());joined.add(entry.getKey()+"="+entry.getValue()+"@"+recipient.getHealth()+"/"+recipient.getMaxHealth());}evidence.put("recipients",joined.toString());return new TemporaryOfferingTerms(0,0,0,evidence);}
        @Override public void commit(ServerPlayerEntity donor,TemporaryOfferings.Station station,TemporaryOfferingClaim claim){Map<UUID,Float> shares=parseShares(claim.terms().evidence().get("recipients"));int cost=Integer.parseInt(claim.terms().evidence().get("donor_cost"));if(donor.getHealth()<=cost)throw new IllegalStateException("Donor health changed after the durable claim");Map<UUID,ServerPlayerEntity> recipients=new LinkedHashMap<>();for(UUID id:shares.keySet()){ServerPlayerEntity recipient=donor.getEntityWorld().getServer().getPlayerManager().getPlayer(id);if(recipient==null||!PlayRuntime.eligiblePlayers(donor.getEntityWorld().getServer()).contains(recipient))throw new IllegalStateException("A claimed healing recipient became unavailable");recipients.put(id,recipient);}donor.setHealth(donor.getHealth()-cost);for(var entry:shares.entrySet()){ServerPlayerEntity recipient=recipients.get(entry.getKey());recipient.heal(Math.min(entry.getValue(),recipient.getMaxHealth()-recipient.getHealth()));}aftermath(donor,station,"You prayed, and the sculk answered. Pain passes outward, and the dark draws close around the others.");}
    }
    private static final class RepairHandler extends Handler {
        @Override public TemporaryOfferingTerms preview(ServerPlayerEntity player,TemporaryOfferings.Station station){var config=AltarOfferingConfig.get().repair();enabled(config.enabled());if(active(player,REPAIR_ID))throw new IllegalStateException("Swift mending already weighs on this character.");Hand hand=Hand.valueOf(station.context().get("hand"));ItemStack stack=player.getStackInHand(hand);if(stack.isEmpty()||!stack.isDamageable()||stack.getDamage()<=0)throw new IllegalStateException("The activating hand holds no damaged gear.");int amount=Math.max(1,(int)Math.ceil(stack.getMaxDamage()*config.percent()/100.0));Map<String,String> evidence=new TreeMap<>(station.context());evidence.put("item",Registries.ITEM.getId(stack.getItem()).toString());evidence.put("count",Integer.toString(stack.getCount()));evidence.put("damage",Integer.toString(stack.getDamage()));evidence.put("max_damage",Integer.toString(stack.getMaxDamage()));evidence.put("repair",Integer.toString(amount));evidence.put("components",digest(stack.getComponents().toString()));return new TemporaryOfferingTerms(config.seconds()*20L,-config.health(),0,evidence);}
        @Override public void commit(ServerPlayerEntity player,TemporaryOfferings.Station station,TemporaryOfferingClaim claim){Hand hand=Hand.valueOf(claim.terms().evidence().get("hand"));ItemStack stack=player.getStackInHand(hand);var e=claim.terms().evidence();if(stack.isEmpty()||!Registries.ITEM.getId(stack.getItem()).toString().equals(e.get("item"))||stack.getCount()!=Integer.parseInt(e.get("count"))||stack.getDamage()!=Integer.parseInt(e.get("damage"))||stack.getMaxDamage()!=Integer.parseInt(e.get("max_damage"))||!digest(stack.getComponents().toString()).equals(e.get("components")))throw new IllegalStateException("Held gear changed after the durable claim");stack.setDamage(Math.max(0,stack.getDamage()-Integer.parseInt(e.get("repair"))));aftermath(player,station,"You prayed, and the sculk answered. The worn thing draws tight as a hollow ache settles beneath your ribs.");}
    }
    private static final class SightHandler extends Handler {
        @Override public TemporaryOfferingTerms preview(ServerPlayerEntity player,TemporaryOfferings.Station station){var config=AltarOfferingConfig.get().sight();enabled(config.enabled());if(active(player,SIGHT_ID))throw new IllegalStateException("Clear sight is already active for this character.");if(player.experienceLevel<config.levels())throw new IllegalStateException("The Altar finds too little experience to take.");Map<String,String> evidence=new TreeMap<>(station.context());evidence.put("levels",Integer.toString(config.levels()));evidence.put("experience_level",Integer.toString(player.experienceLevel));return new TemporaryOfferingTerms(config.seconds()*20L,0,config.exhaustionPercent(),evidence);}
        @Override public void commit(ServerPlayerEntity player,TemporaryOfferings.Station station,TemporaryOfferingClaim claim){int levels=Integer.parseInt(claim.terms().evidence().get("levels"));if(player.experienceLevel<Integer.parseInt(claim.terms().evidence().get("experience_level"))||player.experienceLevel<levels)throw new IllegalStateException("Experience changed after the durable claim");player.addExperienceLevels(-levels);aftermath(player,station,"You prayed, and the sculk answered. The cave opens before your eyes, and hunger follows close behind.");}
    }
    private static final class HarvestHandler extends Handler {
        @Override public TemporaryOfferingTerms preview(ServerPlayerEntity player,TemporaryOfferings.Station station){var config=AltarOfferingConfig.get().harvest();enabled(config.enabled());var active=TemporaryOfferings.active(player.getEntityWorld().getServer(),AncientAltars.SOURCE).stream().filter(claim->claim.offering().equals(HARVEST_ID)).toList();if(active.stream().anyMatch(claim->claim.station().equals(station.identity())))throw new IllegalStateException("This Altar already carries a quiet harvest.");if(active.size()>=MAX_ACTIVE_HARVESTS)throw new IllegalStateException("Too many Altars already carry a quiet harvest.");int needed=config.bread();StringJoiner slots=new StringJoiner(",");for(int slot=0;slot<player.getInventory().size()&&needed>0;slot++){ItemStack stack=player.getInventory().getStack(slot);if(!stack.isOf(Items.BREAD))continue;int take=Math.min(needed,stack.getCount());slots.add(slot+"="+take+"@"+stack.getCount()+"#"+digest(stack.getComponents().toString()));needed-=take;}if(needed>0)throw new IllegalStateException("The communal offering is incomplete.");Map<String,String> evidence=new TreeMap<>(station.context());evidence.put("bread",Integer.toString(config.bread()));evidence.put("bread_slots",slots.toString());evidence.put("radius",Integer.toString(config.radius()));evidence.put("crop_percent",Integer.toString(config.cropPercent()));evidence.put("growth_percent",Integer.toString(config.growthPercent()));return new TemporaryOfferingTerms(config.seconds()*20L,0,0,evidence);}
        @Override public void commit(ServerPlayerEntity player,TemporaryOfferings.Station station,TemporaryOfferingClaim claim){List<int[]> charges=new ArrayList<>();for(String value:claim.terms().evidence().get("bread_slots").split(",")){String[] sides=value.split("[=@#]");int slot=Integer.parseInt(sides[0]),take=Integer.parseInt(sides[1]),count=Integer.parseInt(sides[2]);ItemStack stack=player.getInventory().getStack(slot);if(!stack.isOf(Items.BREAD)||stack.getCount()!=count||!digest(stack.getComponents().toString()).equals(sides[3]))throw new IllegalStateException("Bread changed after the durable claim");charges.add(new int[]{slot,take});}for(int[] charge:charges)player.getInventory().getStack(charge[0]).decrement(charge[1]);aftermath(player,station,"You prayed, and the sculk answered. The offering sinks away as roots and dark earth stir together.");}
    }
    static Map<UUID,Float> shares(List<ServerPlayerEntity> recipients,float total){LinkedHashMap<UUID,Float> result=new LinkedHashMap<>();float remaining=total;List<ServerPlayerEntity> open=new ArrayList<>(recipients);while(remaining>.0001f&&!open.isEmpty()){float each=remaining/open.size();boolean progress=false;for(var player:new ArrayList<>(open)){float capacity=player.getMaxHealth()-player.getHealth(),amount=Math.min(each,capacity);if(amount>0){result.merge(player.getUuid(),amount,Float::sum);remaining-=amount;progress=true;}if(capacity<=each+.0001f)open.remove(player);}if(!progress)break;}return result;}
    private static Map<UUID,Float> parseShares(String value){LinkedHashMap<UUID,Float> result=new LinkedHashMap<>();for(String part:value.split(",")){int equals=part.indexOf('='),at=part.indexOf('@');result.put(UUID.fromString(part.substring(0,equals)),Float.parseFloat(part.substring(equals+1,at)));}return result;}
    private static String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception error){throw new IllegalStateException(error);}}
    private static void tick(MinecraftServer server){List<TemporaryOfferingClaim> active;try{active=TemporaryOfferings.active(server,AncientAltars.SOURCE);}catch(RuntimeException unavailable){clear(server);return;}Set<UUID> wanted=new HashSet<>();for(var claim:active)if(claim.offering().equals(SIGHT_ID))wanted.add(claim.player());Map<UUID,StatusEffectInstance> tracked=OWNED_SIGHT.computeIfAbsent(server,ignored->new HashMap<>());for(var entry:new ArrayList<>(tracked.entrySet())){ServerPlayerEntity player=server.getPlayerManager().getPlayer(entry.getKey());if(player==null||player.getStatusEffect(StatusEffects.NIGHT_VISION)!=entry.getValue()||!owned(entry.getValue()))tracked.remove(entry.getKey());else if(!wanted.contains(entry.getKey())){player.removeStatusEffect(StatusEffects.NIGHT_VISION);tracked.remove(entry.getKey());}}for(UUID id:wanted){ServerPlayerEntity player=server.getPlayerManager().getPlayer(id);if(player==null||player.hasStatusEffect(StatusEffects.NIGHT_VISION))continue;StatusEffectInstance effect=new StatusEffectInstance(StatusEffects.NIGHT_VISION,StatusEffectInstance.INFINITE,0,false,false,true);((AltarSightEffect)(Object)effect).quietBelow$markAltarSight();if(player.addStatusEffect(effect)&&player.getStatusEffect(StatusEffects.NIGHT_VISION)==effect)tracked.put(id,effect);}if(tracked.isEmpty())OWNED_SIGHT.remove(server);}
    public static boolean owned(StatusEffectInstance effect){return effect!=null&&((AltarSightEffect)(Object)effect).quietBelow$isAltarSight();}
    public static void beforeForeignAddition(ServerPlayerEntity player,StatusEffectInstance incoming){if(owned(incoming)||!incoming.getEffectType().equals(StatusEffects.NIGHT_VISION))return;Map<UUID,StatusEffectInstance> tracked=OWNED_SIGHT.get(player.getEntityWorld().getServer());if(tracked==null)return;StatusEffectInstance ours=tracked.remove(player.getUuid());if(ours!=null&&player.getStatusEffect(StatusEffects.NIGHT_VISION)==ours&&owned(ours))player.removeStatusEffect(StatusEffects.NIGHT_VISION);}
    public static Object persistentEffectData(Object value){if(!(value instanceof List<?> list))throw new IllegalStateException("Native active-effects serialization changed");return list.stream().filter(item->!(item instanceof StatusEffectInstance effect)||!owned(effect)).toList();}
    private static void disconnect(ServerPlayerEntity player){Map<UUID,StatusEffectInstance> tracked=OWNED_SIGHT.get(player.getEntityWorld().getServer());if(tracked==null)return;StatusEffectInstance effect=tracked.remove(player.getUuid());if(effect!=null&&player.getStatusEffect(StatusEffects.NIGHT_VISION)==effect&&owned(effect))player.removeStatusEffect(StatusEffects.NIGHT_VISION);}
    private static void withdrawMarked(ServerPlayerEntity player){StatusEffectInstance effect=player.getStatusEffect(StatusEffects.NIGHT_VISION);if(owned(effect))player.removeStatusEffect(StatusEffects.NIGHT_VISION);}
    private static void clear(MinecraftServer server){Map<UUID,StatusEffectInstance> tracked=OWNED_SIGHT.get(server);if(tracked==null)return;for(UUID id:new ArrayList<>(tracked.keySet())){ServerPlayerEntity player=server.getPlayerManager().getPlayer(id);if(player!=null)disconnect(player);}}
}
